/**
 * `packages/tokens/src/tokens.ts` → `packages/tokens/src/themes/theme.css`.
 *
 * The same shape as `generate-typography-css.mjs` — bare run checks, `--write` writes — and
 * the same reason: a committed generated file that nothing re-derives is a file that drifts.
 * `research/30-implementation-plan.md` §B1 asks for exactly this direction, *"author in
 * TypeScript, generate CSS"*, and the deciding argument is in `tokens.ts`'s own docblock: a
 * provenance tier has no slot in a CSS declaration, so authoring the other way round leaves
 * every tier as prose that nothing can check.
 *
 * ⚠ **No build step, unlike the typography generator.** That one has to `pnpm --filter
 * @gx/core build` first, because it imports `DEFAULT_TYPOGRAPHY` out of `dist/`. This one
 * imports `tokens.ts` directly on Node's native type stripping, which is why that file is
 * restricted to erasable syntax and why the root `engines.node` floor is `>=22.18`. The
 * principle is `check-tokens.mjs`'s: *"a lint gate that needs the build to work cannot check
 * the build."*
 *
 * ⚠ **This generator resolves nothing.** A value arrives as an opaque string and leaves as the
 * same string. `--gx-surface-text-color: var(--gx-ramp-neutral-9)` must still be a `var()` in the output,
 * because re-pointing that indirection is how a theme works — `raw/06` §6.10 warns that much
 * of the tree is `var()` chains rather than literals. There is deliberately no code here that
 * could dereference one.
 */

import { readFile, writeFile } from 'node:fs/promises'
import { fileURLToPath } from 'node:url'

import { collectDeclaredTokens } from './check-tokens.mjs'
import { THEME_VARIANTS, TOKEN_GROUPS, tierCensus } from '../packages/tokens/src/tokens.ts'

/** @typedef {import('../packages/tokens/src/tokens.ts').Token} Token */
/** @typedef {import('../packages/tokens/src/tokens.ts').TokenGroup} TokenGroup */

const THEMES_DIR = fileURLToPath(new URL('../packages/tokens/src/themes/', import.meta.url))
const CSS_TARGET = fileURLToPath(new URL('../packages/tokens/src/themes/theme.css', import.meta.url))
const NAMES_TARGET = fileURLToPath(new URL('../packages/tokens/src/tokens.generated.ts', import.meta.url))

/**
 * The parts of the stylesheet that are structure rather than data.
 *
 * ⚠ These are not tokens and must not become tokens. The cascade layer order, the `:where()`
 * wrapper and the `@import` are the *mechanism* the tokens are delivered through; a theme that
 * could restate them could break the delivery. 43-theming.md §2.
 */
const HEADER = `/*
 * @generated by scripts/generate-tokens-css.mjs — do not edit by hand.
 * Source of truth: packages/tokens/src/tokens.ts. Run \`pnpm generate:tokens\`.
 *
 * @gx/tokens — The Emission-Line Rail, the default theme.
 *
 * The Rail theme is the default. Neutral dark/light escape-hatch variants are emitted below
 * from the typed source and are selected explicitly by class or data attribute.
 *
 * This file is the one place in the repo where raw colour and length literals are
 * legal, and only as custom-property values — see 43-theming.md §6.1 and the gate in
 * scripts/check-tokens.mjs. \`color: #b4e4fd\` would be rejected here too.
 */

@layer gx.tokens, gx.theme, gx.overrides;
@import './typography.css' layer(gx.tokens);
`

/**
 * Wrap prose into the repo's starred block-comment form at a given indent.
 *
 * ⚠ Single-line notes get the one-line form and multi-line notes get the starred block. The
 * hand-authored file used a third, hanging-indent form for two-line notes; normalising to two
 * forms changes bytes and changes no declaration, which is the whole licence a generated file
 * has to tidy up after the hand it replaced.
 *
 * @param {string} text
 * @param {string} indent
 * @returns {string[]}
 */
function blockComment(text, indent) {
  const lines = text.split('\n')
  if (lines.length === 1) return [`${indent}/* ${lines[0]} */`]
  return [
    `${indent}/*`,
    ...lines.map((line) => (line === '' ? `${indent} *` : `${indent} * ${line}`)),
    `${indent} */`,
  ]
}

/**
 * One declaration, plus whatever documentation hangs off it.
 *
 * ⚠ `tier` and `source` are **not** emitted. They are the reason the source is TypeScript, and
 * writing them back out as comments would recreate the unchecked prose this direction exists
 * to remove — the CSS would look authoritative while the field stayed the only thing anyone
 * could verify. `tokens.ts` and the DTCG export are where a tier is legible.
 *
 * @param {Token} token
 * @param {string} indent
 * @returns {string[]}
 */
function renderToken(token, indent) {
  const lines = []
  if (token.note !== undefined) lines.push(...blockComment(token.note, indent))
  const aside = token.aside === undefined ? '' : ` /* ${token.aside} */`
  lines.push(`${indent}--gx-${token.name}: ${token.value};${aside}`)
  return lines
}

/**
 * @param {readonly TokenGroup[]} groups
 * @param {string} indent
 * @returns {string[]}
 */
function renderGroups(groups, indent) {
  const lines = []
  for (const [index, group] of groups.entries()) {
    if (index > 0) lines.push('')
    const heading = ` --- ${group.title} ${'-'.repeat(Math.max(1, 76 - indent.length - group.title.length))}`
    lines.push(`${indent}/*${heading} */`)
    if (group.note !== undefined) lines.push(...blockComment(group.note, indent))
    for (const token of group.tokens) lines.push(...renderToken(token, indent))
  }
  return lines
}

/**
 * @param {readonly Token[]} tokens
 * @param {string} indent
 * @returns {string[]}
 */
function renderOverrides(tokens, indent) {
  return tokens.flatMap((token) => {
    const aside = token.aside === undefined ? '' : ` /* ${token.aside} */`
    return [`${indent}--gx-${token.name}: ${token.value};${aside}`]
  })
}

export function renderTokensCss() {
  const lines = [HEADER.trimEnd(), '', '@layer gx.tokens {']

  lines.push(
    ...blockComment(
      [
        '`:where(:root)` has specificity 0,0,0 so ANY selector beats it — a theme class, a',
        "consumer's own override, an inline style. A plain `:root` would tie with",
        '`.gx-theme-rail-light` (both 0,1,0) and leave the winner to source order, which breaks',
        'the moment a bundler reorders imports. 43-theming.md §2.',
      ].join('\n'),
      '  ',
    ),
    '  :where(:root) {',
    ...renderGroups(TOKEN_GROUPS, '    '),
    '  }',
  )

  for (const variant of THEME_VARIANTS) {
    if (variant.prefersColorScheme !== undefined) {
      lines.push(
        '',
        ...blockComment(
          [
            'prefers-color-scheme picks the ground; a class picks the world. Four combinations, not',
            `two — 43-theming.md §2. ${variant.note ?? ''}`.trimEnd(),
            '',
            'The media and explicit class blocks are emitted from the same authored override list',
            'so the two selection paths cannot drift.',
          ].join('\n'),
          '  ',
        ),
        `  @media (prefers-color-scheme: ${variant.prefersColorScheme}) {`,
        '    :where(:root) {',
        ...renderOverrides(variant.overrides, '      '),
        '    }',
        '  }',
      )
    } else {
      lines.push(
        '',
        ...blockComment(
          [
            'Explicit escape-hatch theme. It is intentionally class/data-attribute only:',
            'never emit it into an unscoped prefers-color-scheme root block.',
            variant.note ?? '',
          ].filter(Boolean).join('\n'),
          '  ',
        ),
        '',
        ...blockComment('The data attribute path is explicit and scoped to the selected world.', '  '),
        `  :where(:root)[data-gx-theme='${variant.id}'] {`,
        ...renderOverrides(variant.overrides, '    '),
        '  }',
        '',
        ...blockComment('The class path is explicit and scoped to the selected world.', '  '),
        `  .gx-theme-${variant.id} {`,
        ...renderOverrides(variant.overrides, '    '),
        '  }',
      )
      continue
    }

    lines.push(
      '',
      ...blockComment(
        [
          'Pinning the world explicitly, for a consumer who does not want to follow the OS. The',
          'bare class is there so it beats the `:where()` default regardless of source order.',
        ].join('\n'),
        '  ',
      ),
      `  :where(:root)[data-gx-theme='${variant.id}'],`,
      `  .gx-theme-${variant.id} {`,
      ...renderOverrides(variant.overrides, '    '),
      '  }',
    )
  }

  lines.push('}')
  return `${lines.join('\n')}\n`
}

/**
 * The name list `@gx/tokens` exports, as a `const` tuple.
 *
 * ⚠ **Derived from the emitted CSS, not from `TOKEN_GROUPS` — and the difference is the whole
 * point.** Two generators write into the themes directory: this one, from typed TS, and
 * `generate-typography-css.mjs`, from the font metrics in `@gx/core`. A list built from
 * `TOKEN_GROUPS` alone would silently omit all 29 typography tokens. Reading what is actually
 * declared is the only source that spans both, and it is the same function the G7 membership
 * rule tests against, so the exported list and the gate can never disagree about what exists.
 *
 * ⚠ This replaces a hand-maintained array that had **already drifted**: at the moment it was
 * generated, all seven A6 motion tokens were live in `theme.css`, referenced by `chart.css`,
 * asserted by G19 — and absent from the list. `index.ts` predicted this in its own docblock
 * and the prediction came true one milestone later.
 *
 * @param {ReadonlySet<string>} declared Full custom-property spellings, e.g. `--gx-surface-color`.
 * @returns {string}
 */
export function renderTokenNames(declared) {
  const names = [...declared].map((property) => property.slice('--gx-'.length)).sort()
  return [
    '/**',
    ' * @generated by scripts/generate-tokens-css.mjs — do not edit by hand.',
    ' * Run `pnpm generate:tokens`.',
    ' *',
    ' * Every `--gx-*` custom property the shipped themes declare, sorted, without the prefix.',
    ' * Sourced by parsing `./themes/*.css`, so it spans BOTH generators — the typed token tree',
    ' * in `./tokens.ts` and the fitted typography in `@gx/core` — without either having to know',
    ' * about the other.',
    ' */',
    'export const GX_TOKENS = [',
    ...names.map((name) => `  '${name}',`),
    '] as const',
    '',
  ].join('\n')
}

// --- CLI ---------------------------------------------------------------------------

const invokedDirectly =
  process.argv[1] !== undefined && import.meta.url === new URL(`file://${process.argv[1]}`).href

if (invokedDirectly) {
  const expectedCss = renderTokensCss()
  const census = tierCensus()
  const write = process.argv.includes('--write')

  // ⚠ The CSS is written FIRST and the names are read back off disk afterwards, rather than
  // both being derived in memory. The name list has to span `typography.css` too, and that
  // file is another generator's output — so the only description of "every token that exists"
  // that is true of the shipped package is the one taken from the shipped package.
  if (write) await writeFile(CSS_TARGET, expectedCss)
  const expectedNames = renderTokenNames(await collectDeclaredTokens(THEMES_DIR))

  if (write) {
    await writeFile(NAMES_TARGET, expectedNames)
    console.log('tokens: theme.css and tokens.generated.ts written.')
  } else {
    const actualCss = await readFile(CSS_TARGET, 'utf8').catch(() => '')
    const actualNames = await readFile(NAMES_TARGET, 'utf8').catch(() => '')
    const stale = [
      actualCss === expectedCss ? '' : 'themes/theme.css',
      actualNames === expectedNames ? '' : 'tokens.generated.ts',
    ].filter(Boolean)
    if (stale.length > 0) {
      console.error(`tokens: ${stale.join(' and ')} stale — run \`pnpm generate:tokens\`.`)
      process.exit(1)
    }
    console.log('tokens: generated output is current.')
  }

  // ⚠ Reported on every run, in both modes, and deliberately NOT a failure. These two counts
  // are how much of B1 is left: `untiered` falls by transcribing raw/06 §6.2–6.9, `unverified`
  // only by finding a source or taking a measurement. Printing them keeps the remaining work
  // attached to the build instead of to a plan document that goes stale.
  const owed = census.untiered + census.unverified
  const tiered = census['A-lit'] + census['A-impl'] + census.B + census.C
  console.log(
    `tokens: ${tiered + owed} declared — ` +
      `A-lit ${census['A-lit']}, A-impl ${census['A-impl']}, B ${census.B}, C ${census.C}; ` +
      `${census.unverified} unverified, ${census.untiered} untiered (${owed} owed to B1).`,
  )
}
